/// Trimmed, uppercased, with a "!" at the end.
fn shout(s: &str) -> String {
    format!("{}!", s.trim().to_uppercase())
}

/// Number of vowels (a, e, i, o, u in any case).
fn count_vowels(s: &str) -> usize {
    let mut n = 0;
    for c in s.chars() {
        match c.to_ascii_lowercase() {
            'a' | 'e' | 'i' | 'o' | 'u' => n += 1,
            _ => {}
        }
    }
    n
}

/// First letter of every word, uppercased.
fn initials(name: &str) -> String {
    let mut out = String::new();
    for word in name.split_whitespace() {
        if let Some(c) = word.chars().next() {
            out.extend(c.to_uppercase());
        }
    }
    out
}

fn main() {
    println!("{}", shout("  ahoy there "));
    println!("{}", count_vowels("Black Pearl"));
    println!("{}", initials("jack sparrow"));
}

