/// The number in s, or 0 if there is none.
fn parse_amount(s: &str) -> u32 {
    s.trim().parse().unwrap_or(0)
}

/// Sum of the amounts in "name: amount" lines.
fn tally(text: &str) -> u32 {
    let mut total = 0;
    for line in text.lines() {
        if let Some((_, amount)) = line.split_once(':') {
            total += parse_amount(amount);
        }
    }
    total
}

/// Single spaces between words, none at the ends.
fn tidy(s: &str) -> String {
    let mut out = String::new();
    for word in s.split_whitespace() {
        if !out.is_empty() {
            out.push(' ');
        }
        out.push_str(word);
    }
    out
}

fn main() {
    println!("{}", tally("rum: 12\ngold: 30\nsmudged\nmaps: x"));
    println!("[{}]", tidy("  rum   and\tgold "));
}

