use std::io::{self, Read};

/// Decodes one message line (already trimmed, not blank, not a comment).
/// Unknown messages start with "?? ".
fn decode(line: &str) -> String {
    let unknown = format!("?? {line}");
    let Some((verb, text)) = line.split_once(':') else {
        return unknown;
    };
    let text = text.trim();
    match verb.trim().to_lowercase().as_str() {
        "shout" => format!("{}!", text.to_uppercase()),
        "whisper" => format!("{}...", text.to_lowercase()),
        "reverse" => text.chars().rev().collect(),
        "count" => format!(
            "{} words, {} chars",
            text.split_whitespace().count(),
            text.chars().count()
        ),
        _ => unknown,
    }
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let mut total = 0;
    let mut decoded = 0;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let out = decode(line);
        total += 1;
        if !out.starts_with("?? ") {
            decoded += 1;
        }
        println!("{out}");
    }
    println!("decoded {decoded} of {total} messages");
}
